-- Postavke (podaci firme, logo, moderni izgled) za HERAK – usluga prijevoza i građevinske mehanizacije.
-- 1) Prvo u Authentication → Users dodaj njegovog korisnika.
-- 2) Ispod zamijeni UPISI-EMAIL@PRIMJER.HR njegovim e-mailom (red "where email = ...") i klikni Run.
-- Rezultat mora vratiti jedan red (user_id); ako je prazno, e-mail nije točan.
-- Ostale postavke koje je već sam upisao (npr. PDV, brojač) ostaju; prepisuju se samo ovi podaci.

insert into public.settings (user_id, data, updated_at)
select id, '{"firma": "USLUGA PRIJEVOZA I\nGRAĐEVINSKE MEHANIZACIJE\n**„HERAK“ VL. DRAGAN HERAK**", "adresa": "Sveti Lovreč, Selina 25", "oib": "31639003348", "dodatno": "", "odgovornaOsoba": "Dragan Herak", "predlozak": "moderni", "boja": "#f7941d", "logo": "data:image/jpeg;base64,"}'::jsonb, now()
from auth.users
where email = lower('UPISI-EMAIL@PRIMJER.HR')
on conflict (user_id) do update set data = public.settings.data || excluded.data, updated_at = now()
returning user_id;
